import numpy as np
import pandas as pd

TARGET_COLUMN = 'target'

class DecisionTree:
    def __init__(self, max_depth=3):
        self.max_depth = max_depth

    def fit(self, X, y):
        self.tree = self._build_tree(X, y, depth=0)

    def _build_tree(self, X, y, depth):
        if depth >= self.max_depth or len(np.unique(y)) == 1 or len(y) < 2:
            return np.bincount(y).argmax()

        best_gini = 1.0
        best_split = None

        for f in range(X.shape[1]):
            # Use percentiles to speed up and reduce splits
            thresholds = np.percentile(X[:, f], [25, 50, 75])
            for t in thresholds:
                left_idx = X[:, f] <= t
                right_idx = X[:, f] > t

                if sum(left_idx) == 0 or sum(right_idx) == 0:
                    continue

                pl = sum(left_idx) / len(y)
                pr = sum(right_idx) / len(y)

                gini_l = 1.0 - sum((np.bincount(y[left_idx], minlength=2) / sum(left_idx))**2)
                gini_r = 1.0 - sum((np.bincount(y[right_idx], minlength=2) / sum(right_idx))**2)

                gini = pl * gini_l + pr * gini_r

                if gini < best_gini:
                    best_gini = gini
                    best_split = (f, t, left_idx, right_idx)

        if best_split is None:
            return np.bincount(y).argmax()

        f, t, left_idx, right_idx = best_split

        return {
            'feature': f,
            'threshold': t,
            'left': self._build_tree(X[left_idx], y[left_idx], depth + 1),
            'right': self._build_tree(X[right_idx], y[right_idx], depth + 1)
        }

    def predict_one(self, x, tree):
        if not isinstance(tree, dict):
            return tree
        if x[tree['feature']] <= tree['threshold']:
            return self.predict_one(x, tree['left'])
        else:
            return self.predict_one(x, tree['right'])

    def predict(self, X):
        return np.array([self.predict_one(x, self.tree) for x in X])

def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    all_features = [c for c in train.columns if c != TARGET_COLUMN]

    X_train = train[all_features].values
    y_train = train[TARGET_COLUMN].values

    dt = DecisionTree(max_depth=3)
    dt.fit(X_train, y_train)

    X_test = test[all_features].values
    pred = dt.predict(X_test)

    predictions = pd.DataFrame({"prediction": pred})
    predictions.to_csv(output_csv, index=False)
